import {newQuote,calculate,transfer,parseBackup,COST_TYPES,WORK_TYPES,SCHEMA_VERSION} from './pricing.js';
const bases=await fetch('bases.json').then(r=>{if(!r.ok)throw Error('Base prices could not be loaded.');return r.json();});
const KEY='shedhouse.pricing.v1';let storageError=false;let stored={};try{stored=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{storageError=true;}
const fresh=v=>newQuote(v);const state={variant:stored.variant==='KIT_PLUS_WORK'?'KIT_PLUS_WORK':'KIT_ONLY',drafts:{KIT_ONLY:fresh('KIT_ONLY'),KIT_PLUS_WORK:fresh('KIT_PLUS_WORK'),...stored.drafts},saved:Array.isArray(stored.saved)?stored.saved:[],step:'details',view:'quote'};
const $=s=>document.querySelector(s);const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null||!Number.isFinite(n)?'—':new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',minimumFractionDigits:2}).format(n);
const prettyDate=s=>s&&!isNaN(Date.parse(s+'T00:00:00Z'))?new Intl.DateTimeFormat('en-NZ',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z')):'—';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',book:'<path d="M4 3h14a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V5a2 2 0 0 1 1-2zM3 17h17M7 7h9M7 11h7"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3m.1 4h.01"/>',save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2zM7 3v6h10V3M7 21v-8h10v8"/>',back:'<path d="m11 5-7 7 7 7m-7-7h16"/>',print:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v7H6z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>'};
const icon=(name)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.file}</svg>`;
const q=()=>state.drafts[state.variant];const isPlus=()=>state.variant==='KIT_PLUS_WORK';
const labelVariant=v=>v==='KIT_ONLY'?'Kit-set only':'Kit-set + site & build';
function persist(){try{localStorage.setItem(KEY,JSON.stringify({variant:state.variant,drafts:state.drafts,saved:state.saved}));storageError=false;}catch{storageError=true;}const el=$('#save-status');if(el)el.textContent=storageError?'Browser storage unavailable · export a backup':'Draft saved in this browser';}
let timer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const button=(action,text,cls='secondary',ic='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function field(key,label,{type='text',placeholder='',wide=false,help='',rows=0}={}){const value=q()[key]??'';return `<label class="field ${wide?'wide':''}"><span>${label}</span>${rows?`<textarea data-field="${key}" rows="${rows}" placeholder="${escape(placeholder)}">${escape(value)}</textarea>`:`<input data-field="${key}" type="${type}" value="${escape(value)}" placeholder="${escape(placeholder)}" ${type==='number'?'step="any" min="0"':''}>`}${help?`<small>${help}</small>`:''}</label>`;}
function render(){const quote=q();const nav=state.view;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-action="home" aria-label="Shed House pricing home"><img src="assets/sh-logo-white.png" alt="Shed House"></a><div class="workspace-label">SALES WORKSPACE</div><nav aria-label="Main navigation"><button class="nav-item ${nav==='quote'?'active':''}" data-action="home">${icon('grid')}Pricing workspace<span class="nav-dot"></span></button><button class="nav-item ${nav==='saved'?'active':''}" data-action="saved">${icon('file')}Saved quotes<span class="nav-count">${state.saved.length}</span></button><button class="nav-item ${nav==='bases'?'active':''}" data-action="bases">${icon('book')}Base proposals</button></nav><div class="sidebar-note"><span class="eyebrow">TWO WAYS TO PRICE</span><p>One shared foundation.<br>Separate quote workflows.</p><div class="mini-rule"></div><span>Built for Shed House.<br>Prepared for SHP.</span></div><button class="nav-item ${nav==='guide'?'active':''} bottom-nav" data-action="guide">${icon('help')}How pricing works</button><div class="profile"><span class="avatar">SH</span><div><b>Shed House</b><small>Internal pricing</small></div><span class="online-dot"></span></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Shed House <span>/</span> <b>${nav==='quote'?'Pricing workspace':nav==='saved'?'Saved quotes':nav==='bases'?'Base proposals':'Pricing guide'}</b></div><span class="private-label">${icon('shield')}SH INTERNAL</span></header><main>${nav==='quote'?workspace():nav==='saved'?savedView():nav==='bases'?baseView():guideView()}</main><footer class="site-footer"><span>SHED HOUSE <span class="dot-sep">·</span> Pricing workspace</span><span>NZD · GST shown separately</span></footer></div></div>`;if(nav==='quote')updateSummary();}
function workspace(){const plus=isPlus();const steps=[['details','Project details'],['supply','Supply & pricing'],...(plus?[['work','Work packages']]:[]),['review','Review quote']];return `<div class="page-heading"><div><div class="eyebrow">QUOTE BUILDER</div><h1>${plus?'Kit-set + site & build':'Kit-set pricing'}</h1><p>${plus?'Supply and selected work, priced together.':'A clear price for the right kit-set.'}</p></div>${button('new','New quote','secondary','plus')}</div><div class="workflow-switch" role="group" aria-label="Pricing workflow"><button data-variant="KIT_ONLY" class="${!plus?'selected':''}"><span class="switch-icon">${icon('file')}</span><span><b>Kit-set only</b><small>Supply, freight & extras</small></span>${!plus?'<span class="selected-dot"></span>':''}</button><button data-variant="KIT_PLUS_WORK" class="${plus?'selected':''}"><span class="switch-icon">${icon('grid')}</span><span><b>Kit-set + site & build</b><small>Slab, site work & erection</small></span>${plus?'<span class="selected-dot"></span>':''}</button></div><div class="workspace-grid"><div class="editor"><div class="steps" aria-label="Quote steps">${steps.map(([key,label],i)=>`<button data-step="${key}" class="${state.step===key?'current':''}" ${state.step===key?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</div>${state.step==='details'?details():state.step==='supply'?supply():state.step==='work'?work():review()}<div class="editor-actions"><span id="save-status">${storageError?'Browser storage unavailable · export a backup':'Draft saved in this browser'}</span><div>${button('save','Save quote','secondary','save')}${state.step!=='review'?button('next','Continue','primary','arrow'):button('backup','Download backup','secondary','down')}</div></div></div><aside id="summary" class="summary" aria-label="Quote summary"></aside></div>`;}
function card(title,sub,body,tag=''){return `<section class="card"><div class="card-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${tag?`<span class="tag">${tag}</span>`:''}</div>${body}</section>`;}
function details(){return card('Let’s start with the project','The details that will appear on your customer quote.',`<div class="form-grid">${field('customer','Customer name',{placeholder:'e.g. Alex Taylor'})}${field('reference','Quote reference',{placeholder:'e.g. SH-2026-001'})}${field('site','Site address',{wide:true,placeholder:'Street address, town or city'})}${field('date','Quote date',{type:'date'})}${field('validUntil','Valid until',{type:'date'})}${field('specification','Building specification',{wide:true,rows:3,placeholder:'Length × span × knee height, roof pitch, cladding, openings and any design requirements.'})}</div><div class="callout subtle">${icon('file')}<div><b>Your two drafts stay separate.</b><p>Switch workflows at any time. Each keeps its own project details, costs and selected work.</p></div></div>`)+card('Supplier details','Connect this quote to the current supplier pricing.',`<div class="form-grid">${field('supplierReference','Supplier / kit reference',{placeholder:'Supplier and kit reference'})}${field('supplierQuote','Supplier quotation reference',{placeholder:'Quote number or revision'})}</div>`);}
function supply(){const quote=q(),r=calculate(quote,bases),b=r.base;return card('Choose your starting point','Historical proposals provide a reference, not a current supplier quote.',`<label class="field"><span>Base proposal</span><select data-field="baseId">${bases.map(b=>`<option value="${b.id}" ${Number(quote.baseId)===b.id?'selected':''}>${b.name}</option>`).join('')}</select></label><div class="base-spec"><div><small>BUILDING</small><b>${b.length} × ${b.span} m</b></div><div><small>KNEE HEIGHT</small><b>${b.knee} m</b></div><div><small>SUPPLIER</small><b>${escape(b.supplier)}</b></div><span class="tag amber">Historical reference</span></div><p class="fine-print">Dimensions describe the base proposal. They do not generate or rescale the supplier cost.</p>`)+card('Supply costs','Enter current costs excluding GST. Leave blank to use the historical cost; enter 0 to remove it.',`<div class="table-wrap"><table class="cost-table"><thead><tr><th>Supply item</th><th>Historical</th><th>Current cost</th><th>Active cost</th></tr></thead><tbody>${r.activeCosts.map(row=>`<tr><td><b>${row.label}</b>${row.key==='secondary'?'<small>Included in both Lang proposals</small>':''}</td><td>${money(row.source)}</td><td><div class="money-input"><span>$</span><input aria-label="${row.label} current cost" type="number" min="0" step="0.01" data-cost="${row.key}" value="${escape(quote.costs[row.key]??'')}" placeholder="Use history"></div></td><td data-active-cost="${row.key}">${money(row.cost)}</td></tr>`).join('')}</tbody></table></div>`)+card('Set your selling price','Use the base markup or enter your own pricing rate.',`<div class="form-grid three"><label class="field"><span>Pricing method</span><select data-field="method"><option ${quote.method==='Markup'?'selected':''}>Markup</option><option ${quote.method==='Gross margin'?'selected':''}>Gross margin</option></select></label>${field('rate','Rate override (%)',{type:'number',placeholder:(r.rate*100).toFixed(2),help:'Blank preserves the base selling price.'})}${field('gst','GST rate (%)',{type:'number'})}</div><div class="formula-note">${quote.method==='Markup'?'Cost × (1 + markup)':'Cost ÷ (1 − gross margin)'}<span>Active rate: <b data-active-rate>${(r.rate*100).toFixed(2)}%</b></span></div>`);}
function work(){return card('Select the work to include','Each package is separate from the kit-set supply price. Include all relevant materials, labour and subcontract costs.',`<div class="package-list">${q().work.map((w,i)=>`<div class="package ${w.included?'included':''}"><div class="package-heading"><label class="toggle-label"><input type="checkbox" data-work="${i}" data-key="included" ${w.included?'checked':''}><span class="toggle"></span><b>${WORK_TYPES[i][1]}</b></label><span data-work-sale="${i}">${w.included?money(calculate(q(),bases).work[i].sale):'Not included'}</span></div>${w.included?`<div class="package-fields"><label class="field wide"><span>Scope / supplier reference</span><input data-work="${i}" data-key="scope" value="${escape(w.scope)}" placeholder="Describe the work and supplier quote"></label><label class="field"><span>Unit</span><select data-work="${i}" data-key="unit">${['sum','m2','m3','m','hr','each'].map(u=>`<option ${w.unit===u?'selected':''}>${u}</option>`).join('')}</select></label>${['quantity','unitCost','markup'].map((key,n)=>`<label class="field"><span>${['Quantity','Cost / unit ($)','Markup (%)'][n]}</span><input type="number" min="0" step="any" data-work="${i}" data-key="${key}" value="${escape(w[key])}" placeholder="${key==='quantity'?'e.g. 1':'Required'}"></label>`).join('')}</div>`:''}</div>`).join('')}</div><div class="callout subtle">${icon('help')}<div><b>Use 1 × cost for a lump-sum quote.</b><p>Keep kit inclusions out of these packages to avoid double counting. Enter 0% explicitly when no markup applies.</p></div></div>`);}
function review(){return card('Define the scope','Be specific about the supply, selected work and agreed terms.',`<div class="form-grid">${field('inclusions','Included supply / work',{rows:3,wide:true,placeholder:'Describe the exact kit-set inclusions and selected work.'})}${field('exclusions','Excluded work',{rows:3,wide:true,placeholder:'List project-specific exclusions, including work not selected.'})}${field('terms','Supply and payment terms',{rows:3,wide:true,placeholder:'Payment stages, delivery arrangements and agreed conditions.'})}</div><div class="confirmation"><label><input data-field="costsConfirmed" type="checkbox" ${q().costsConfirmed?'checked':''}><span>I have confirmed the current supplier costs${isPlus()?' and all selected work costs':''}.</span></label><label><input data-field="scopeConfirmed" type="checkbox" ${q().scopeConfirmed?'checked':''}><span>I have reviewed the specification, inclusions, exclusions and terms.</span></label></div>`)+`<section class="card customer-preview"><div class="card-heading"><div><h2>Customer quote preview</h2><p>Internal costs and margins stay in this workspace.</p></div><span class="tag">CUSTOMER VIEW</span></div><div id="quote-review">${customerQuote(q(),calculate(q(),bases))}</div></section>`;}
function customerQuote(quote,r){return `<article class="quote-document ${r.ready?'':'is-draft'}"><div class="doc-header"><img src="assets/sh-logo.png" alt="Shed House"><div><small>${isPlus()?'KIT-SET & SELECTED WORK':'KIT-SET SUPPLY'}</small><h2>Proposal</h2><b>${escape(quote.reference||'Quote reference')}</b></div></div>${!r.ready?'<div class="draft-notice">DRAFT · Complete the quote review before issuing.</div>':''}<div class="doc-parties"><div><small>PREPARED FOR</small><b>${escape(quote.customer||'Customer name')}</b><p>${escape(quote.site||'Site address')}</p></div><div><small>QUOTE DATE</small><p>${escape(prettyDate(quote.date))}</p><small>VALID UNTIL</small><p>${escape(prettyDate(quote.validUntil))}</p></div></div><div class="doc-spec">${escape(quote.specification||'Building specification').replace(/\n/g,'<br>')}</div><table><thead><tr><th>Supply / work package</th><th>NZD excl. GST</th></tr></thead><tbody><tr><td>Kit-set supply</td><td>${r.ready?money(r.kitSale):'—'}</td></tr>${r.work.filter(w=>w.included).map(w=>`<tr><td>${w.label}<small>${escape(w.scope)}</small></td><td>${r.ready?money(w.sale):'—'}</td></tr>`).join('')}</tbody></table><dl class="doc-totals"><div><dt>Subtotal excluding GST</dt><dd>${r.ready?money(r.subtotal):'—'}</dd></div><div><dt>GST (${r.gstRate===null?'—':(r.gstRate===null?'—':roundDisplay(r.gstRate*100))}%)</dt><dd>${r.ready?money(r.gst):'—'}</dd></div><div class="total"><dt>Total including GST</dt><dd>${r.ready?money(r.total):'—'}</dd></div></dl>${[['Included supply / work',quote.inclusions],['Excluded work',quote.exclusions],['Supply & payment terms',quote.terms]].map(([label,txt])=>`<section class="doc-section"><h3>${label}</h3><p>${escape(txt||'To be completed').replace(/\n/g,'<br>')}</p></section>`).join('')}<div class="doc-footer">SHED HOUSE <span>info@shedhouse.co.nz · www.shedhouse.co.nz</span></div></article>`;}
const roundDisplay=n=>Number.isFinite(n)?Number(n.toFixed(2)):'—';
function updateSummary(){const r=calculate(q(),bases);const target=$('#summary');if(!target)return;target.innerHTML=`<div class="summary-top"><div class="eyebrow">YOUR QUOTE</div><span class="status ${r.ready?'ready':''}">${r.ready?icon('check'):''}${r.ready?'Ready to issue':'Draft'}</span></div><h2>${escape(q().reference||'New quote')}</h2><p class="summary-customer">${escape(q().customer||'Customer details to come')}</p><div class="summary-type">${icon('file')}${labelVariant(state.variant)}</div><dl class="summary-numbers"><div><dt>Kit-set supply</dt><dd>${money(r.kitSale)}</dd></div>${isPlus()?`<div><dt>Selected work <span>(${r.work.filter(w=>w.included).length})</span></dt><dd>${money(r.workSale)}</dd></div>`:''}<div class="summary-sub"><dt>Subtotal excl. GST</dt><dd>${money(r.subtotal)}</dd></div><div><dt>GST (${(r.gstRate===null?'—':roundDisplay(r.gstRate*100))}%)</dt><dd>${money(r.gst)}</dd></div></dl><div class="grand-total"><span>Total including GST</span><strong>${money(r.total)}</strong><small>NZD</small></div><details class="internal-metrics"><summary>Internal price breakdown</summary><div><span>Supply cost</span><b>${money(r.kitCost)}</b></div><div><span>Gross profit excl. GST</span><b>${money(r.profit)}</b></div><small>Amounts are provisional until reviewed.</small></details>${r.ready?`<div class="readiness success">${icon('check')}<div><b>Ready for your customer</b><p>Costs, scope and terms confirmed.</p></div></div>`:`<div class="readiness">${icon('clock')}<div><b>${r.issues.length} ${r.issues.length===1?'detail':'details'} to finish</b><p>${escape(r.issues[0]||'Review the quote.')}</p>${r.issues.length>1?`<details><summary>See all requirements</summary><ul>${r.issues.slice(1).map(x=>`<li>${escape(x)}</li>`).join('')}</ul></details>`:''}</div></div>`}<button class="btn primary full" data-action="${state.step==='review'?'print':'review'}" ${state.step==='review'&&!r.ready?'disabled':''}>${icon(state.step==='review'?'print':'arrow')}${state.step==='review'?'Print customer quote':'Review quote'}</button><button class="text-button full" data-action="export">${icon('down')}Export for SHP <span>JSON</span></button><p class="summary-footnote">${r.ready?'Customer-ready prices.':'Draft prices are for internal review.'}<br>Quotes stay on this device. Download a backup to keep a separate copy.</p>`;
 r.activeCosts.forEach(c=>{const cell=$(`[data-active-cost="${c.key}"]`);if(cell)cell.textContent=money(c.cost);});r.work.forEach((w,i)=>{const cell=$(`[data-work-sale="${i}"]`);if(cell)cell.textContent=w.included?money(w.sale):'Not included';});const rate=$('[data-active-rate]');if(rate)rate.textContent=roundDisplay(r.rate*100)+'%';if($('#quote-review'))$('#quote-review').innerHTML=customerQuote(q(),r);}
function savedView(){const list=state.saved.filter(s=>s.variant===state.variant);return `<div class="page-heading"><div><div class="eyebrow">QUOTE LIBRARY</div><h1>Saved quotes</h1><p>Separate quote records, saved in this browser.</p></div><div class="heading-actions">${button('import','Import backup','secondary','down')}${button('new','New quote','primary','plus')}</div></div><div class="filter-tabs">${['KIT_ONLY','KIT_PLUS_WORK'].map(v=>`<button class="${state.variant===v?'active':''}" data-variant="${v}">${labelVariant(v)} <span>${state.saved.filter(q=>q.variant===v).length}</span></button>`).join('')}</div>${list.length?`<section class="card table-wrap"><table class="saved-table"><thead><tr><th>Quote / customer</th><th>Updated</th><th>Total incl. GST</th><th>Status</th><th></th></tr></thead><tbody>${list.map(s=>{const r=calculate(s,bases);return `<tr><td><b>${escape(s.reference||'Untitled quote')}</b><small>${escape(s.customer||'Customer not set')}</small></td><td>${new Intl.DateTimeFormat('en-NZ',{dateStyle:'medium'}).format(new Date(s.updatedAt))}</td><td>${money(r.total)}</td><td><span class="status ${r.ready?'ready':''}">${r.ready?'Ready to issue':'Draft'}</span></td><td><button class="text-button" data-open="${escape(s.id)}">Open ${icon('arrow')}</button><button class="text-button muted" data-delete="${escape(s.id)}" aria-label="Delete ${escape(s.reference||'untitled quote')}">Delete</button></td></tr>`;}).join('')}</tbody></table></section>`:`<div class="empty-state"><div class="empty-icon">${icon('file')}</div><h2>Your next quote starts here.</h2><p>Save a quote from the workspace to keep it in this ${state.variant==='KIT_ONLY'?'kit-set':'site & build'} library.</p>${button('home','Go to workspace','primary','arrow')}</div>`}`;}
function baseView(){return `<div class="page-heading"><div><div class="eyebrow">PRICING REFERENCES</div><h1>Base proposals</h1><p>The five starting points behind your pricing workbooks.</p></div><span class="tag amber">Historical costs</span></div><div class="callout reference-note">${icon('book')}<div><b>Use a current supplier quotation for every customer price.</b><p>Dimensions are descriptive. These references do not calculate a bill of materials or a new supplier cost.</p></div></div><div class="base-grid">${bases.map(b=>`<section class="card base-card"><div class="base-card-top"><span class="base-number">0${b.id}</span><span class="tag">${escape(b.jobReference)}</span></div><h2>${escape(b.name)}</h2><p>${b.length} × ${b.span} m <span>·</span> ${b.knee} m knee</p><dl><div><dt>Primary kit cost</dt><dd>${money(b.primary)}</dd></div><div><dt>Secondary kit cost</dt><dd>${money(b.secondary)}</dd></div><div><dt>Historical markup</dt><dd>${b.markup*100}%</dd></div><div class="base-sale"><dt>Kit selling price excl. GST</dt><dd>${money(b.historicalSale)}</dd></div></dl><details><summary>Source reference</summary><p>${escape(b.sourceFile)}</p><p>${escape(b.sourceCells)}</p></details><button class="btn secondary full" data-use-base="${b.id}">Use as starting point ${icon('arrow')}</button></section>`).join('')}</div>`;}
function guideView(){return `<div class="page-heading"><div><div class="eyebrow">WORKSPACE GUIDE</div><h1>From supplier cost to customer quote.</h1><p>A familiar pricing process, with fewer spreadsheet steps.</p></div></div><div class="guide-grid">${card('01 · Choose a workflow','',`<p>Kit-set only includes supply, freight and supply extras. Kit-set + site & build adds separately selected slab, site, erection and other work packages. Their drafts and saved quote libraries remain separate.</p>`)}${card('02 · Confirm the supplier cost','',`<p>Each base carries its historical kit cost and markup. Enter current supplier costs, exact specifications and reference numbers. A blank override uses history; a zero override removes that cost.</p>`)}${card('03 · Set the selling price','',`<p><b>Markup:</b> cost × (1 + rate).<br><b>Gross margin:</b> cost ÷ (1 − rate).</p><p>A blank rate preserves the selected base’s original selling price. Work packages have their own explicit markups. GST is calculated on the combined subtotal and rounded to cents.</p>`)}${card('04 · Review and issue','',`<p>Complete customer details, validity, inclusions, exclusions and payment terms. Confirm current costs and scope. Customer printing becomes available when every requirement is complete. Your browser’s print dialog can save a PDF.</p>`)}${card('Save, back up & restore','',`<p>Drafts and saved quotes are stored only in this browser. They are not shared with other devices or users. Download a backup JSON from the review step, and restore it using Import backup in Saved quotes. Imported quotes require fresh confirmations.</p>${button('import','Import a quote backup','secondary','down')}`)}${card('Prepared for SHP','',`<p>The framework-independent pricing engine serves both workflows. SHP exports use schema ${SCHEMA_VERSION}, the same field keys as the spreadsheets, and an explicit KIT_ONLY or KIT_PLUS_WORK variant.</p><p>Exported draft records retain their draft status and outstanding requirements. SHP import mapping and shared storage are future integration steps.</p>`)}${card('Shed House identity','',`<div class="swatches"><span style="background:#20353C"></span><span style="background:#FAA21F"></span><span style="background:#F3EBE1"></span></div><p>Dark turquoise, construction yellow and linen. The supplied logo is used intact. Typography specifies the approved Work Sans alternative, with system fallbacks.</p>`)}</div>`;}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const fileName=()=>String(q().reference||'SH-quote').replace(/[^\w-]/g,'-');
function save(){const item=structuredClone(q());item.updatedAt=new Date().toISOString();const i=state.saved.findIndex(s=>s.id===item.id);if(i>=0)state.saved[i]=item;else state.saved.unshift(item);persist();const count=$('.nav-count');if(count)count.textContent=state.saved.length;toast(storageError?'Could not save in this browser. Download a backup.':'Quote saved to '+labelVariant(state.variant)+'.');}
function changeBase(id){if(!bases.some(b=>b.id===Number(id)))return;if((Object.values(q().costs).some(x=>x!==''&&x!==null)||q().costsConfirmed||q().scopeConfirmed)&&!confirm('Changing the base clears current kit cost overrides and both confirmations. Continue?')){render();return;}q().baseId=Number(id);q().costs={};q().rate='';q().costsConfirmed=false;q().scopeConfirmed=false;persist();}
document.addEventListener('click',e=>{
 const variant=e.target.closest('[data-variant]');if(variant){state.variant=variant.dataset.variant;state.step='details';persist();render();return;}
 const step=e.target.closest('[data-step]');if(step){state.step=step.dataset.step;render();return;}
 const open=e.target.closest('[data-open]');if(open){const item=state.saved.find(s=>s.id===open.dataset.open);state.variant=item.variant;state.drafts[item.variant]=structuredClone(item);state.view='quote';state.step='details';persist();render();return;}
 const del=e.target.closest('[data-delete]');if(del){if(confirm('Delete this saved quote? The current draft will remain.')){state.saved=state.saved.filter(s=>s.id!==del.dataset.delete);persist();render();}return;}
 const use=e.target.closest('[data-use-base]');if(use){changeBase(use.dataset.useBase);state.view='quote';state.step='supply';render();return;}
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;e.preventDefault();
 if(['home','saved','bases','guide'].includes(action)){state.view=action==='home'?'quote':action;render();}
 if(action==='new'){if(!confirm('Start a new '+labelVariant(state.variant)+' quote? Save or download your current draft first if you need to keep it.'))return;state.drafts[state.variant]=fresh(state.variant);state.step='details';state.view='quote';persist();render();}
 if(action==='next'){const steps=['details','supply',...(isPlus()?['work']:[]),'review'];state.step=steps[steps.indexOf(state.step)+1]||'review';render();window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='review'){state.step='review';render();window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='save')save();
 if(action==='export'){download(transfer(q(),bases),fileName()+'-shp.json');toast('SHP record exported · '+(calculate(q(),bases).ready?'Ready to issue':'Draft'));}
 if(action==='backup')download({format:'sh-pricing-backup',schema_version:SCHEMA_VERSION,quote:q()},fileName()+'-backup.json');
 if(action==='import')$('#import-file').click();
 if(action==='print'){if(!calculate(q(),bases).ready){toast('Complete the quote requirements before printing.');return;}window.print();}
});
function onInput(e){const el=e.target;if(el.dataset.cost){q().costs[el.dataset.cost]=el.value;q().costsConfirmed=false;persist();updateSummary();return;}if(el.dataset.work!==undefined){const item=q().work[Number(el.dataset.work)];item[el.dataset.key]=el.type==='checkbox'?el.checked:el.value;q().costsConfirmed=false;q().scopeConfirmed=false;persist();if(el.type==='checkbox')render();else updateSummary();return;}const field=el.dataset.field;if(!field||field==='baseId')return;q()[field]=el.type==='checkbox'?el.checked:el.value;if(!['costsConfirmed','scopeConfirmed'].includes(field)){if(['method','rate','gst'].includes(field))q().costsConfirmed=false;else q().scopeConfirmed=false;}persist();if(el.tagName==='SELECT')render();else updateSummary();}
document.addEventListener('input',onInput);
document.addEventListener('change',e=>{if(e.target.dataset.field==='baseId'){changeBase(e.target.value);render();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1_000_000)throw Error('Backup files must be smaller than 1 MB.');const quote=parseBackup(await file.text());save();state.variant=quote.variant;state.drafts[quote.variant]=quote;state.view='quote';state.step='details';persist();render();toast('Backup restored. Review costs and scope before issuing.');}catch(err){toast(err.message||'Could not read this backup.');}e.target.value='';});
render();
